from qiskit import QuantumCircuit
from math import pi
qc = QuantumCircuit(3)
for j in reversed(range(3)):
    qc.h(j)
    for k in reversed(range(j)):
        qc.cp(pi / 2 ** (j - k), k, j)
for i in range(3 // 2):
    qc.swap(i, 3 - 1 - i)
qc = qc.inverse()

